1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
8	
9	/**
10	 * The single source of truth for an owner's derived {@code identityKey} and its parts. All duplicate
11	 * detection is now expressed through this one key:
12	 *
13	 * <pre>identityKey = normalizedTelephone + '|' + (email or empty) + '|' + householdId</pre>
14	 *
15	 * <p>Two owners are duplicates only when their <em>whole</em> identityKey is equal. Because the
16	 * telephone is part of the key, two members of the same household (same householdId) with different
17	 * telephones have different identityKeys and are both allowed; only an exact full-key match is a
18	 * duplicate.
19	 *
20	 * <p>The household component is the deterministic id derived from the normalized lastName and postcode
21	 * (see {@link #deriveHouseholdId}).
22	 */
23	public final class OwnerIdentity {
24	
25	    private OwnerIdentity() {
26	    }
27	
28	    /**
29	     * The identityKey from its already-known parts. Telephone is canonicalized to E.164 and email is
30	     * lower-cased so differing formats or case do not hide a match; a null household is the empty
31	     * string.
32	     */
33	    public static String key(String telephone, String email, String householdId) {
34	        return canonicalTelephone(telephone) + '|' + normalizedEmail(email) + '|'
35	                + (householdId == null ? "" : householdId);
36	    }
37	
38	    /**
39	     * The identityKey for the raw parts of a create request or an existing owner — the one derivation
40	     * the duplicate check applies to both sides of a comparison, so a request and an existing owner are
41	     * keyed identically. Derives the household component from the lastName and postcode (see
42	     * {@link #householdIdOf}) and defers to {@link #key}.
43	     */
44	    public static String keyOf(String telephone, String email, String lastName, String postcode) {
45	        return key(telephone, email, householdIdOf(lastName, postcode));
46	    }
47	
48	    /**
49	     * The E.164 form used for comparison. A value that is already E.164 is returned unchanged; a value
50	     * that predates E.164 storage is normalized on the fly, falling back to its bare digits if it
51	     * cannot form valid E.164.
52	     */
53	    public static String canonicalTelephone(String value) {
54	        try {
55	            return OwnerTelephone.toE164(value);
56	        }
57	        catch (InvalidTelephoneException ex) {
58	            return value == null ? "" : value.replaceAll("\\D", "");
59	        }
60	    }
61	
62	    /** The email lower-cased and trimmed, or the empty string when null or blank. */
63	    public static String normalizedEmail(String value) {
64	        if (value == null || value.isBlank()) {
65	            return "";
66	        }
67	        return value.trim().toLowerCase();
68	    }
69	
70	    /** Lower-cased, trimmed, with runs of whitespace collapsed to a single space. */
71	    public static String normalizeName(String value) {
72	        if (value == null) {
73	            return "";
74	        }
75	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
76	    }
77	
78	    /**
79	     * The deterministic household id: the first 12 hex characters of SHA-256 over
80	     * {@code normalizedLastName + '|' + postcode}. Owners with the same normalized lastName and
81	     * postcode therefore resolve to the same value automatically, so the household is keyed on
82	     * (lastName, postcode). A null postcode is treated as the empty string.
83	     */
84	    public static String deriveHouseholdId(String normalizedLastName, String postcode) {
85	        return sha256Hex(normalizedLastName + '|' + (postcode == null ? "" : postcode), 12);
86	    }
87	
88	    /**
89	     * The household id for a raw (un-normalized) {@code lastName} and {@code postcode} — normalizes the
90	     * lastName and defers to {@link #deriveHouseholdId}. This is the one derivation every household
91	     * check shares, so two owners resolve to the same household exactly when this returns the same
92	     * value.
93	     */
94	    public static String householdIdOf(String lastName, String postcode) {
95	        return deriveHouseholdId(normalizeName(lastName), postcode);
96	    }
97	
98	    /**
99	     * HASH8: the first 8 upper-case hex characters of SHA-256 over {@code normalizedTelephone +
100	     * lastName}, where the telephone is canonicalized to E.164. This is the hashed component of the
101	     * owner's {@code customerCode} ({@code <REGION>-<HASH8>}).
102	     */
103	    public static String customerHash(String telephone, String lastName) {
104	        return sha256Hex(canonicalTelephone(telephone) + (lastName == null ? "" : lastName), 8);
105	    }
106	
107	    /**
108	     * The first {@code hexChars} upper-case hex characters of SHA-256 over the UTF-8 bytes of
109	     * {@code input} — the shared encoding behind every hash-derived identity part.
110	     */
111	    static String sha256Hex(String input, int hexChars) {
112	        StringBuilder sb = new StringBuilder(hexChars);
113	        for (byte b : sha256(input)) {
114	            sb.append(String.format("%02X", b));
115	            if (sb.length() >= hexChars) {
116	                break;
117	            }
118	        }
119	        return sb.substring(0, hexChars);
120	    }
121	
122	    /**
123	     * The SHA-256 digest of the UTF-8 bytes of {@code input} — the shared primitive every hash-derived
124	     * identity part is encoded from.
125	     */
126	    static byte[] sha256(String input) {
127	        try {
128	            return MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
129	        }
130	        catch (NoSuchAlgorithmException ex) {
131	            throw new IllegalStateException("SHA-256 not available", ex);
132	        }
133	    }
134	}
