3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The duplicate check for {@code POST /api/owners}, keyed on the whole {@code identityKey} — the
11	 * single source of truth for duplicate detection (see {@link OwnerIdentity}). Two owners are
12	 * duplicates only when their <em>whole</em> identityKey
13	 * ({@code normalizedTelephone + '|' + email + '|' + householdId}) is equal; because the telephone is
14	 * part of the key, two members of the same household (same lastName and postcode) with different
15	 * telephones have different identityKeys and are both allowed — which is what lets a household hold
16	 * more than one member. On an exact full-key match it throws {@link DuplicateIdentityException},
17	 * handled globally as 409. A request that sets {@code sharesHousehold} bypasses the check entirely.
18	 */
19	public class EnsureIdentityUnique {
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws DuplicateIdentityException {
23	        // A declared household member is allowed to join an existing household, so it bypasses the
24	        // duplicate block entirely.
25	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
26	            return;
27	        }
28	
29	        String identityKey = OwnerIdentity.keyOf(request.getTelephone(), request.getEmail(),
30	                request.getLastName(), request.getPostcode());
31	        for (Owner existing : ownerRepository.findAll()) {
32	            // A soft-deleted owner no longer blocks a create.
33	            if (Boolean.TRUE.equals(existing.getDeleted())) {
34	                continue;
35	            }
36	            String existingKey = OwnerIdentity.keyOf(existing.getTelephone(), existing.getEmail(),
37	                    existing.getLastName(), existing.getPostcode());
38	            if (identityKey.equals(existingKey)) {
39	                throw new DuplicateIdentityException(identityKey);
40	            }
41	        }
42	    }
43	}
