3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	import java.util.regex.Pattern;
6	
7	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
8	
9	/**
10	 * Normalizes an owner {@code telephone} to E.164 form. Spaces, dashes and brackets are stripped; a
11	 * value that already carries a leading {@code '+'} and country code keeps them, otherwise country
12	 * code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
13	 * The result must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'} becomes
14	 * {@code '+61412345678'} and {@code '+64 21 123 456'} becomes {@code '+6421123456'}.
15	 *
16	 * <p>For known country codes the national-number length is also checked: {@code '+61'} requires 9
17	 * national digits and {@code '+1'} requires 10. A number whose national part is the wrong length for
18	 * its country is rejected. Country codes not listed here are only length-checked by the E.164 range.
19	 *
20	 * <p>{@link #toDisplay} renders a stored E.164 number for humans: the {@code '+'} country code, a
21	 * space, then the national digits grouped in threes (e.g. {@code '+61412345678'} becomes
22	 * {@code '+61 412 345 678'}).
23	 */
24	public final class OwnerTelephone {
25	
26	    /** E.164: a {@code '+'} followed by 8 to 15 digits. */
27	    private static final Pattern E164 = Pattern.compile("\\+[0-9]{8,15}");
28	
29	    /** Formatting characters removed before interpreting the number: spaces, dashes and brackets. */
30	    private static final Pattern FORMATTING = Pattern.compile("[\\s()\\-]");
31	
32	    /**
33	     * Country code (digits after the {@code '+'}) to required national-number length. Ordered
34	     * longest-prefix first so {@code '61'} is matched before the shorter {@code '1'}.
35	     */
36	    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();
37	    static {
38	        NATIONAL_LENGTHS.put("61", 9);
39	        NATIONAL_LENGTHS.put("1", 10);
40	    }
41	
42	    private OwnerTelephone() {
43	    }
44	
45	    /**
46	     * @return the telephone in E.164 form.
47	     * @throws InvalidTelephoneException when the value cannot form a valid E.164 number.
48	     */
49	    static String toE164(String telephone) throws InvalidTelephoneException {
50	        if (telephone == null) {
51	            throw new InvalidTelephoneException(null);
52	        }
53	        String stripped = FORMATTING.matcher(telephone).replaceAll("");
54	        String e164;
55	        if (stripped.startsWith("+")) {
56	            e164 = stripped;
57	        } else {
58	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
59	            e164 = "+61" + national;
60	        }
61	        if (!E164.matcher(e164).matches()) {
62	            throw new InvalidTelephoneException(telephone);
63	        }
64	        String digits = e164.substring(1);
65	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTHS.entrySet()) {
66	            if (digits.startsWith(country.getKey())) {
67	                int nationalLength = digits.length() - country.getKey().length();
68	                if (nationalLength != country.getValue()) {
69	                    throw new InvalidTelephoneException(telephone);
70	                }
71	                break;
72	            }
73	        }
74	        return e164;
75	    }
76	
77	    /**
78	     * Formats a stored E.164 telephone for display: the {@code '+'} country code, a space, then the
79	     * national digits grouped in threes. Known country codes ({@code '+61'}, {@code '+1'}) split the
80	     * country code from the national number; otherwise the whole run of digits is grouped in threes.
81	     *
82	     * @param e164 the stored E.164 number (a {@code '+'} followed by digits).
83	     * @return the human-readable form, e.g. {@code '+61 412 345 678'}, or {@code null} when
84	     *         {@code e164} is null.
85	     */
86	    public static String toDisplay(String e164) {
87	        if (e164 == null) {
88	            return null;
89	        }
90	        String digits = e164.startsWith("+") ? e164.substring(1) : e164;
91	        String countryCode = null;
92	        String national = digits;
93	        for (String code : NATIONAL_LENGTHS.keySet()) {
94	            if (digits.startsWith(code)) {
95	                countryCode = code;
96	                national = digits.substring(code.length());
97	                break;
98	            }
99	        }
100	        String grouped = groupInThrees(national);
101	        return countryCode == null ? "+" + grouped : "+" + countryCode + " " + grouped;
102	    }
103	
104	    /** Groups a run of digits into space-separated groups of three, from the left. */
105	    private static String groupInThrees(String digits) {
106	        StringBuilder builder = new StringBuilder();
107	        for (int i = 0; i < digits.length(); i++) {
108	            if (i > 0 && i % 3 == 0) {
109	                builder.append(' ');
110	            }
111	            builder.append(digits.charAt(i));
112	        }
113	        return builder.toString();
114	    }
115	}
